insert into public.flashcards(course_id,lesson_id,topic_id,subject_id,title,description,cards,mode,is_public,created_by,updated_at)
values ('4f37aa03-fe66-4336-aa47-357032b17e1f'::uuid,'423b8a70-08f4-447f-8cf8-e865b15db420'::uuid,'229a18ff-7286-40ec-840b-9976a3883e7d'::uuid,'69929a0c-a8ce-43df-9efe-8f95b82adf0d'::uuid,'Primary 4 French: EXAMEN End of term and final primary school assessment - — Flashcards','Pre-generated retrieval-practice cards grounded in this published lesson.','[{"cue":"Bonjour","back":"Hello / Good morning","front":"What does \"Bonjour\" mean in English?","difficulty":"easy","sourceKind":"lesson-vocabulary"},{"cue":"Bonsoir","back":"Good evening","front":"What does \"Bonsoir\" mean in English?","difficulty":"easy","sourceKind":"lesson-vocabulary"},{"cue":"Au revoir","back":"Goodbye","front":"What does \"Au revoir\" mean in English?","difficulty":"easy","sourceKind":"lesson-vocabulary"},{"cue":"mercredi","back":"mercredi","front":"What is \"Wednesday\" in French?","difficulty":"medium","sourceKind":"lesson-vocabulary"},{"cue":"la mère","back":"la mère","front":"What is \"mother\" in French?","difficulty":"medium","sourceKind":"lesson-vocabulary"},{"cue":"le livre","back":"le livre","front":"What is \"book\" in French?","difficulty":"medium","sourceKind":"lesson-vocabulary"},{"cue":"le chien","back":"le chien","front":"What is \"dog\" in French?","difficulty":"hard","sourceKind":"lesson-vocabulary"},{"cue":"vert / verte","back":"vert / verte","front":"What is \"green\" in French?","difficulty":"hard","sourceKind":"lesson-vocabulary"},{"cue":"vingt-cinq","back":"vingt-cinq","front":"What is \"twenty-five\" in French?","difficulty":"hard","sourceKind":"lesson-vocabulary"},{"cue":"les yeux","back":"les yeux","front":"What is \"eyes\" in French?","difficulty":"hard","sourceKind":"lesson-vocabulary"}]'::jsonb,'curriculum-prebuilt',true,null,now())
on conflict (lesson_id) where is_public=true and created_by is null and mode='curriculum-prebuilt'
do update set course_id=excluded.course_id,topic_id=excluded.topic_id,subject_id=excluded.subject_id,title=excluded.title,description=excluded.description,cards=excluded.cards,updated_at=now();

insert into public.lesson_practice_sets(lesson_id,content_fingerprint,questions,generation_method,source_version,updated_at)
values ('423b8a70-08f4-447f-8cf8-e865b15db420'::uuid,'6ccb326d1fd6932fb405d4337d65481600d94c491d24609b28dc1a160327841f','[{"options":["Hello / Good morning","Good evening","Goodbye","Thank you"],"difficulty":"easy","explanation":"The lesson vocabulary table gives \"Bonjour\" as \"Hello / Good morning\".","questionText":"What does \"Bonjour\" mean in English?","questionType":"multiple-choice","correctAnswer":"Hello / Good morning","provenanceBasis":"published-lesson","curriculumObjective":"Recall basic French greetings.","misconceptionTested":"Distinguishes common French greetings."},{"options":["lundi","mardi","mercredi","vendredi"],"difficulty":"easy","explanation":"The lesson lists Wednesday as \"mercredi\".","questionText":"Which French word means \"Wednesday\"?","questionType":"multiple-choice","correctAnswer":"mercredi","provenanceBasis":"published-lesson","curriculumObjective":"Recall French days of the week.","misconceptionTested":"Distinguishes days of the week."},{"options":["le père","la mère","le frère","la sœur"],"difficulty":"easy","explanation":"The family vocabulary table gives \"la mère\" as mother.","questionText":"Which French expression means \"mother\"?","questionType":"multiple-choice","correctAnswer":"la mère","provenanceBasis":"published-lesson","curriculumObjective":"Recall French family vocabulary.","misconceptionTested":"Distinguishes close family vocabulary."},{"options":["le cahier","le stylo","le livre","le sac"],"difficulty":"medium","explanation":"The school-object vocabulary table gives \"le livre\" as book.","questionText":"Which French expression means \"book\"?","questionType":"multiple-choice","correctAnswer":"le livre","provenanceBasis":"published-lesson","curriculumObjective":"Recall French school objects.","misconceptionTested":"Distinguishes school-object vocabulary."},{"options":["le chat","le chien","le cheval","le mouton"],"difficulty":"medium","explanation":"The animal vocabulary table gives \"le chien\" as dog.","questionText":"Which French expression means \"dog\"?","questionType":"multiple-choice","correctAnswer":"le chien","provenanceBasis":"published-lesson","curriculumObjective":"Recall French animal vocabulary.","misconceptionTested":"Distinguishes animal vocabulary."},{"options":["rouge","jaune","vert / verte","noir / noire"],"difficulty":"medium","explanation":"The colour vocabulary table gives \"vert / verte\" as green.","questionText":"Which French form means \"green\"?","questionType":"multiple-choice","correctAnswer":"vert / verte","provenanceBasis":"published-lesson","curriculumObjective":"Recall French colours.","misconceptionTested":"Distinguishes French colour vocabulary."},{"options":["vingt","vingt et un","vingt-cinq","trente"],"difficulty":"hard","explanation":"The lesson number list gives 25 as \"vingt-cinq\".","questionText":"How is twenty-five written in French in this lesson?","questionType":"multiple-choice","correctAnswer":"vingt-cinq","provenanceBasis":"published-lesson","curriculumObjective":"Recall French numbers.","misconceptionTested":"Distinguishes nearby French number forms."},{"options":["la tête","les yeux","le nez","la bouche"],"difficulty":"hard","explanation":"The body-parts vocabulary table gives \"les yeux\" as eyes.","questionText":"Which French expression means \"eyes\"?","questionType":"multiple-choice","correctAnswer":"les yeux","provenanceBasis":"published-lesson","curriculumObjective":"Recall French body parts.","misconceptionTested":"Distinguishes French body-part vocabulary."}]'::jsonb,'grounded-fallback',3,now())
on conflict (lesson_id) do update
set content_fingerprint=excluded.content_fingerprint,questions=excluded.questions,generation_method=excluded.generation_method,source_version=excluded.source_version,updated_at=now();

