insert into public.flashcards(course_id,lesson_id,topic_id,subject_id,title,description,cards,mode,is_public,created_by,updated_at)
values ('528445b1-e9af-4d65-be4a-9aaa93864011'::uuid,'90d2ef7c-f3b7-4228-96b6-aacebf33049c'::uuid,'923e70ab-2e13-4de2-868a-85cac88fc5dc'::uuid,'2b562f70-3fa3-4d08-8244-e7a144fd2059'::uuid,'Primary 2 Social and Citizenship Studies: Understanding — What is money? — Flashcards','Pre-generated retrieval-practice cards grounded in this published lesson.','[{"cue":"money","back":"Money is something generally accepted as a means of payment for goods and services.","front":"What is money?","difficulty":"easy","sourceKind":"lesson-fact"},{"cue":"naira","back":"Nigeria uses the naira (₦).","front":"What currency does Nigeria use?","difficulty":"easy","sourceKind":"lesson-fact"},{"cue":"kobo","back":"The kobo is the smaller unit of the naira.","front":"What is the smaller unit of the naira?","difficulty":"easy","sourceKind":"lesson-fact"},{"cue":"100 kobo","back":"100 kobo make one naira.","front":"How many kobo make one naira?","difficulty":"medium","sourceKind":"lesson-fact"},{"cue":"barter","back":"Barter is the direct exchange of goods or services.","front":"What is barter?","difficulty":"medium","sourceKind":"lesson-fact"},{"cue":"barter difficulty","back":"Barter can be difficult when each person does not want what the other person has.","front":"Why can barter be difficult?","difficulty":"medium","sourceKind":"lesson-fact"},{"cue":"uses of money","back":"Money can be used to buy goods, pay for services, compare prices, save for future needs, or make payments without direct exchange.","front":"Name one use of money taught in the lesson.","difficulty":"hard","sourceKind":"lesson-fact"},{"cue":"money habits","back":"Keep money safely, avoid waste, save when appropriate, and ask a trusted adult before unfamiliar purchases.","front":"What is one good money habit for children?","difficulty":"hard","sourceKind":"lesson-fact"},{"cue":"forms of money","back":"Banknotes and coins.","front":"What are two broad forms of Nigerian currency mentioned in the lesson?","difficulty":"hard","sourceKind":"lesson-fact"},{"cue":"currency changes","back":"Currency denominations and designs can change.","front":"Why should old currency examples not automatically be treated as current?","difficulty":"hard","sourceKind":"lesson-fact"}]'::jsonb,'curriculum-prebuilt',true,null,now())
on conflict (lesson_id) where is_public=true and created_by is null and mode='curriculum-prebuilt'
