insert into public.lesson_practice_sets(lesson_id,content_fingerprint,questions,generation_method,source_version,updated_at)
values ('90d2ef7c-f3b7-4228-96b6-aacebf33049c'::uuid,'2fba6e55aa6877712ba5a0f908d6ed111e5dbf7d7c70e983fc88e4a3f85fc6a6','[{"options":["A means of payment generally accepted for goods and services","Only coins used in markets","Any item that can be exchanged once","Only paper notes kept in banks"],"difficulty":"easy","explanation":"The lesson defines money as something generally accepted as a means of payment for goods and services.","questionText":"Which statement best defines money?","questionType":"multiple-choice","correctAnswer":"A means of payment generally accepted for goods and services","provenanceBasis":"published-lesson","curriculumObjective":"Understand what money is.","misconceptionTested":"Distinguishes money from only one physical form."},{"options":["Cedi","Naira","Dollar","Pound"],"difficulty":"easy","explanation":"The lesson states that Nigeria uses the naira.","questionText":"What is Nigeria’s currency?","questionType":"multiple-choice","correctAnswer":"Naira","provenanceBasis":"published-lesson","curriculumObjective":"Identify Nigeria’s currency.","misconceptionTested":"Identifies Nigeria’s currency."},{"options":["10","20","50","100"],"difficulty":"easy","explanation":"The lesson states that 100 kobo make one naira.","questionText":"How many kobo make one naira?","questionType":"multiple-choice","correctAnswer":"100","provenanceBasis":"published-lesson","curriculumObjective":"Understand the smaller currency unit.","misconceptionTested":"Distinguishes the naira-kobo relationship."},{"options":["Saving money for later","Direct exchange of goods or services","Borrowing money from a bank","Printing currency"],"difficulty":"medium","explanation":"The lesson explains barter as exchanging goods or services directly.","questionText":"What is barter?","questionType":"multiple-choice","correctAnswer":"Direct exchange of goods or services","provenanceBasis":"published-lesson","curriculumObjective":"Explain barter.","misconceptionTested":"Distinguishes barter from money-based exchange."},{"options":["Making all goods free","Comparing prices of goods","Stopping all saving","Replacing every service"],"difficulty":"medium","explanation":"The lesson lists comparing prices as one use of money.","questionText":"Which is a use of money taught in the lesson?","questionType":"multiple-choice","correctAnswer":"Comparing prices of goods","provenanceBasis":"published-lesson","curriculumObjective":"Identify uses of money.","misconceptionTested":"Recognises practical uses of money."},{"options":["Waste money quickly","Use counterfeit money","Keep money safely","Buy unfamiliar items without asking"],"difficulty":"medium","explanation":"The lesson recommends keeping money safely and avoiding waste.","questionText":"Which is a good money habit for a child?","questionType":"multiple-choice","correctAnswer":"Keep money safely","provenanceBasis":"published-lesson","curriculumObjective":"Develop good money habits.","misconceptionTested":"Distinguishes responsible from unsafe money habits."},{"options":["Banknotes and coins","Cheques and shares","Gold and silver","Goods and services"],"difficulty":"hard","explanation":"The lesson says Nigerian currency includes banknotes and coins.","questionText":"Which two forms of Nigerian currency are mentioned in the lesson?","questionType":"multiple-choice","correctAnswer":"Banknotes and coins","provenanceBasis":"published-lesson","curriculumObjective":"Recognise forms of money.","misconceptionTested":"Distinguishes forms of currency from other financial items."},{"options":["People may not want what the other person offers","Money is always required for barter","Only children can barter","Barter always uses banknotes"],"difficulty":"hard","explanation":"The lesson notes that barter becomes difficult when each person does not want what the other has.","questionText":"Why can barter be difficult?","questionType":"multiple-choice","correctAnswer":"People may not want what the other person offers","provenanceBasis":"published-lesson","curriculumObjective":"Explain a limitation of barter.","misconceptionTested":"Understands a limitation of direct exchange."}]'::jsonb,'grounded-fallback',3,now())
on conflict (lesson_id) do update
set content_fingerprint=excluded.content_fingerprint,questions=excluded.questions,generation_method=excluded.generation_method,source_version=excluded.source_version,updated_at=now();

